// @ts-check
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import * as contracts from '@vouch/contracts';
import { buildOpenApi, buildSchemaSnapshot } from '@vouch/contracts/tooling';

/** Generated files, committed so reviewers and the contract diff can see them. */
export const GENERATED = {
  openapi: fileURLToPath(new URL('../packages/contracts/openapi.json', import.meta.url)),
  schemas: fileURLToPath(new URL('../packages/contracts/schemas.json', import.meta.url)),
  apiClient: fileURLToPath(new URL('../packages/api-client/src/generated.js', import.meta.url)),
};

/**
 * The api-client's endpoint functions (Phase 11). Runtime code carries only metadata (method,
 * path, auth, idempotency); types come from the contracts through JSDoc type imports, which
 * add nothing to the bundle.
 */
export function buildApiClientSource() {
  const exportNames = new Map(
    Object.entries(contracts).flatMap(([name, value]) =>
      contracts.ENDPOINTS.includes(/** @type {any} */ (value)) ? [[value, name]] : [],
    ),
  );
  const lines = [
    '// @ts-check',
    '// Generated by `pnpm contracts:generate` from packages/contracts. Do not edit.',
    '// Types come from the contracts through JSDoc imports only: nothing here loads zod.',
    '',
    "/** @typedef {import('./client.js').ApiClient} ApiClient */",
    "/** @typedef {import('./client.js').CallInput} CallInput */",
    '',
  ];
  const meta = [];
  for (const endpoint of [...contracts.ENDPOINTS].sort((a, b) => a.id.localeCompare(b.id))) {
    const name = exportNames.get(endpoint);
    if (!name) throw new Error(`endpoint ${endpoint.id} is not exported from @vouch/contracts`);
    const contract = `import('@vouch/contracts').${name}`;
    const parts = [
      endpoint.params ? `params: import('zod').input<typeof ${contract}.params>` : null,
      endpoint.query ? `query?: import('zod').input<typeof ${contract}.query>` : null,
      endpoint.body ? `body: import('zod').input<typeof ${contract}.body>` : null,
      'signal?: AbortSignal',
    ].filter(Boolean);
    meta.push(
      `  ${endpoint.id}: { id: '${endpoint.id}', method: '${endpoint.method}', path: '${endpoint.path}', auth: '${endpoint.auth}', idempotency: '${endpoint.idempotency}' },`,
    );
    lines.push(
      '/**',
      ` * ${endpoint.method} ${endpoint.path} — ${endpoint.summary}`,
      ' * @param {ApiClient} client',
      ` * @param {{ ${parts.join(', ')} }} ${endpoint.params || endpoint.body ? 'input' : '[input]'}`,
      ` * @returns {Promise<import('zod').output<typeof ${contract}.response.schema>>}`,
      ' */',
      `export const ${endpoint.id} = (client, input${endpoint.params || endpoint.body ? '' : ' = {}'}) =>`,
      `  client.call(ENDPOINTS.${endpoint.id}, /** @type {CallInput} */ (input));`,
      '',
    );
  }
  return [
    ...lines,
    "/** Every endpoint, by operationId. @type {Readonly<Record<string, import('./client.js').EndpointMeta>>} */",
    'export const ENDPOINTS = Object.freeze({',
    ...meta,
    '});',
    '',
  ].join('\n');
}

/**
 * Serialises a document exactly as it is committed.
 * @param {unknown} document
 */
export function serialise(document) {
  return `${JSON.stringify(document, null, 2)}\n`;
}

/**
 * Formats generated JavaScript with the repository's Prettier config, so the committed file is
 * stable under \`pnpm format\`.
 * @param {string} source
 * @param {string} path
 */
async function formatted(source, path) {
  const prettier = await import('prettier');
  const options = await prettier.resolveConfig(path);
  return prettier.format(source, { ...options, filepath: path });
}

/**
 * Writes openapi.json and schemas.json, or with `check` reports whether they are stale.
 * @param {{ check: boolean }} options
 * @returns {Promise<string[]>} Files that are (or were) out of date.
 */
export async function generate({ check }) {
  const outputs = [
    [GENERATED.openapi, serialise(buildOpenApi())],
    [GENERATED.schemas, serialise(buildSchemaSnapshot())],
    [GENERATED.apiClient, await formatted(buildApiClientSource(), GENERATED.apiClient)],
  ];
  const stale = [];
  for (const [path, content] of outputs) {
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- fixed paths from GENERATED
    const current = await readFile(path, 'utf8').catch(() => '');
    if (current === content) continue;
    stale.push(path);
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- fixed paths from GENERATED
    if (!check) await writeFile(path, content);
  }
  return stale;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const stale = await generate({ check });
  for (const path of stale) {
    process.stdout.write(`${check ? 'stale' : 'wrote'}: ${path}\n`);
  }
  if (check && stale.length > 0) {
    process.stderr.write('Generated contracts are out of date: run `pnpm contracts:generate`.\n');
    process.exitCode = 1;
  } else if (stale.length === 0) {
    process.stdout.write('Generated contracts are up to date.\n');
  }
}
